**Step 2 – Button component**

Create `components/DownloadButton.tsx`:

```tsx
import { useRouter } from 'next/router';
import { useSession } from 'next-auth/react';

export default function DownloadButton() {
  const { data: session } = useSession();
  const router = useRouter();

  if (!session) return null; // only show to logged‑in users

  const handleDownload = async () => {
    const res = await fetch('/api/download');
    if (!res.ok) {
      alert('Download failed');
      return;
    }
    const blob = await res.blob();
    const url = window.URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', 'my-data.zip');
    document.body.appendChild(link);
    link.click();
    link.parentNode?.removeChild(link);
  };

  return (
    <button type="button" onClick={handleDownload}>
      Download My Data
    </button>
  );
}
```

Add the button to your profile page (e.g., `pages/profile.tsx`):

```tsx
import DownloadButton from '@/components/DownloadButton';

export default function ProfilePage() {
  return (
    <>
      <h1>My Profile</h1>
      <DownloadButton />
    </>
  );
}
```

